 let tables:serde_json::Value=serde_json::from_slice(&output.stdout).unwrap();let tables=tables.as_array().unwrap();let widths:Vec<_>=tables.iter().map(|t|serde_json::json!([t["table"],t["columns"]])).collect();assert_eq!(serde_json::Value::Array(widths),laws()["semanticCells"]["tableWidths"]);assert!(tables.iter().all(|t|t["rows"].as_u64().unwrap()>0));let rows=tables.iter().map(|t|t["rows"].as_u64().unwrap()as usize).sum::<usize>();let cells=tables.iter().map(|t|t["semanticBytes"].as_u64().unwrap()as usize).sum::<usize>();let exact=SqliteDatabaseLimits{max_rows:rows,max_value_bytes:cells,..Default::default()};
 assert_eq!(project(&source,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),database);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=payload(&source,encoding);assert_eq!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap(),expected);let actual=super::super::RemodelingSnapshot::decode_sqlite_snapshot_native(&expected,&mut SqliteSnapshotControl::new(&mut |_|true,exact)).unwrap();same(&actual,&source);actual.retire_sqlite_snapshot();
  for short in[SqliteDatabaseLimits{max_rows:rows-1,..exact},SqliteDatabaseLimits{max_value_bytes:cells-1,..exact}]{assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());assert!(super::super::RemodelingSnapshot::decode_sqlite_snapshot_native(&expected,&mut SqliteSnapshotControl::new(&mut |_|true,short)).is_err());}
 }
